// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0); // plain recipient: low-level payout call always succeeds
        amount = uint96(bound(uint256(amount), 1, type(uint96).max));

        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: uint256(amount)}("");
        vm.assume(depOk);

        vm.prank(actor);
        (bool wOk, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        if (wOk) {
            assertTrue(c.balances(actor) == 0, "balance must be zeroed after successful withdraw");
        }
    }
}
